/**
 * Pure C forward pass for microcontroller deployment.
 * Zero dynamic memory allocation (no malloc/free).
 *
 * @param obs    Input array [5]:
 *                 [0] pitch (rad)
 *                 [1] pitch_rate (rad/s)
 *                 [2] left_wheel_vel * 0.1 (rad/s)
 *                 [3] right_wheel_vel * 0.1 (rad/s)
 * @param action Output array [2]:
 *                 [0] left_torque_norm in [-1.0, 1.0]
 *                 [1] right_torque_norm in [-1.0, 1.0]
 */
static inline void actor_forward(const float* obs, float* action) {
    float buf0[64];
    float buf1[64];
    const float* in  = obs;
    float*       out = buf0;

    // Layer 0: 5 -> 64 (tanh)
    for (int o = 0; o < 64; o++) {
        float acc = layer0_bias[o];
        for (int j = 0; j < 5; j++) {
            acc += layer0_weight[o * 5 + j] * in[j];
        }
        out[o] = tanhf(acc);
    }
    in  = out;
    out = (out == buf0) ? buf1 : buf0;

    // Layer 1: 64 -> 64 (tanh)
    for (int o = 0; o < 64; o++) {
        float acc = layer1_bias[o];
        for (int j = 0; j < 64; j++) {
            acc += layer1_weight[o * 64 + j] * in[j];
        }
        out[o] = tanhf(acc);
    }
    in  = out;
    out = (out == buf0) ? buf1 : buf0;

    // Layer 2: 64 -> 2 (linear + clamp[-1, 1])
    for (int o = 0; o < 2; o++) {
        float acc = layer2_bias[o];
        for (int j = 0; j < 64; j++) {
            acc += layer2_weight[o * 64 + j] * in[j];
        }
        if (acc > 1.0f) acc = 1.0f;
        else if (acc < -1.0f) acc = -1.0f;
        action[o] = acc;
    }

}
